 static void SceneryPrefab(){var root=new GameObject("E235 individual scenery car");var body=new Material(Shader.Find("Universal Render Pipeline/Lit"));body.name="ScenerySteel";body.color=new Color(.52f,.55f,.56f);body.SetFloat("_Metallic",.6f);body.SetFloat("_Smoothness",.4f);AssetDatabase.CreateAsset(body,"Assets/NativeV7/Train/ScenerySteel.mat");var green=new Material(body);green.name="SceneryGreen";green.color=new Color(.33f,.59f,.045f);AssetDatabase.CreateAsset(green,"Assets/NativeV7/Train/SceneryGreen.mat");var glass=new Material(body);glass.name="SceneryGlass";glass.color=new Color(.025f,.065f,.085f);glass.SetFloat("_Smoothness",.85f);AssetDatabase.CreateAsset(glass,"Assets/NativeV7/Train/SceneryGlass.mat");Action<string,Vector3,Vector3,Material> cube=(name,p,size,m)=>{var o=GameObject.CreatePrimitive(PrimitiveType.Cube);o.name=name;UnityEngine.Object.DestroyImmediate(o.GetComponent<Collider>());o.transform.SetParent(root.transform,false);o.transform.localPosition=p;o.transform.localScale=size;o.GetComponent<MeshRenderer>().sharedMaterial=m;};cube("Chassis",new Vector3(0,.8f,0),new Vector3(2.8f,.5f,19.5f),glass);cube("Roof",new Vector3(0,3.98f,0),new Vector3(2.9f,.18f,19.5f),body);for(int side=-1;side<=1;side+=2){cube("Side",new Vector3(side*1.44f,2.47f,0),new Vector3(.08f,2.85f,19.5f),body);cube("Stripe",new Vector3(side*1.487f,2.03f,0),new Vector3(.012f,.26f,19.4f),green);for(int j=0;j<12;j++){float z=-8.4f+j*1.52f;cube("Window",new Vector3(side*1.493f,3.01f,z),new Vector3(.015f,.91f,1.13f),glass);}for(int j=0;j<4;j++){float z=-7.2f+j*4.8f;cube("DoorSeam",new Vector3(side*1.503f,2.47f,z),new Vector3(.01f,2.73f,.026f),glass);}for(int bogie=-1;bogie<=1;bogie+=2)for(int axle=-1;axle<=1;axle+=2){var wheel=GameObject.CreatePrimitive(PrimitiveType.Cylinder);UnityEngine.Object.DestroyImmediate(wheel.GetComponent<Collider>());wheel.transform.SetParent(root.transform,false);wheel.transform.localPosition=new Vector3(side*.66f,.44f,bogie*6.4f+axle*.9f);wheel.transform.localRotation=Quaternion.Euler(0,0,90);wheel.transform.localScale=new Vector3(.86f,.065f,.86f);wheel.GetComponent<MeshRenderer>().sharedMaterial=glass;}}for(int end=-1;end<=1;end+=2){cube("End",new Vector3(0,2.5f,end*9.75f),new Vector3(2.86f,2.9f,.07f),body);cube("EndWindow",new Vector3(0,3.03f,end*9.793f),new Vector3(2.1f,.94f,.012f),glass);}var renderers=root.GetComponentsInChildren<MeshRenderer>();foreach(var m in new[]{body,green,glass}){var combines=renderers.Where(r=>r.sharedMaterial==m).Select(r=>new CombineInstance{mesh=r.GetComponent<MeshFilter>().sharedMesh,transform=r.transform.localToWorldMatrix}).ToArray();var mesh=new Mesh{indexFormat=IndexFormat.UInt32};mesh.CombineMeshes(combines,true,true);AssetDatabase.CreateAsset(mesh,"Assets/NativeV7/Train/Scenery_"+m.name+".asset");var o=new GameObject("Batched exterior",typeof(MeshFilter),typeof(MeshRenderer));o.transform.SetParent(root.transform,false);o.GetComponent<MeshFilter>().sharedMesh=mesh;o.GetComponent<MeshRenderer>().sharedMaterial=m;}foreach(var r in renderers)UnityEngine.Object.DestroyImmediate(r.gameObject);PrefabUtility.SaveAsPrefabAsset(root,"Assets/Resources/Train/SceneryCar.prefab");UnityEngine.Object.DestroyImmediate(root);}
 static void Atmosphere(UniversalRendererData renderer){var shader=Shader.Find("RailDrivingSimulator/Atmosphere");if(!shader||ShaderUtil.ShaderHasError(shader))throw new Exception("Atmosphere shader compilation failed");int N=64;var noise=new Texture3D(N,N,N,TextureFormat.RGBA32,true){name="CloudDensity",wrapMode=TextureWrapMode.Repeat,filterMode=FilterMode.Trilinear};var pixels=new Color[N*N*N];for(int z=0;z<N;z++)for(int y=0;y<N;y++)for(int x=0;x<N;x++){float value=(Mathf.PerlinNoise(x*.095f+z*.017f,y*.095f+z*.041f)+Mathf.PerlinNoise(z*.095f+x*.031f,x*.095f+y*.011f))*.5f;pixels[x+N*(y+N*z)]=new Color(value,value,value,1);}noise.SetPixels(pixels);noise.Apply(true,true);AssetDatabase.CreateAsset(noise,"Assets/Settings/CloudDensity.asset");var mat=new Material(shader);mat.SetTexture("_Noise",noise);AssetDatabase.CreateAsset(mat,"Assets/Settings/Atmosphere.mat");var feature=ScriptableObject.CreateInstance<AtmosphereFeature>();feature.name="True raymarched atmosphere";feature.atmosphere=mat;renderer.rendererFeatures.Add(feature);AssetDatabase.AddObjectToAsset(feature,renderer);EditorUtility.SetDirty(renderer);}
